import{_ as e,o as d,c as o,a2 as c}from"./chunks/framework.BM5YPQmL.js";const n=JSON.parse('{"title":"隐藏的调试接口","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/debug-interfaces.md","filePath":"zh/dev/debug-interfaces.md"}'),a={name:"zh/dev/debug-interfaces.md"};function r(s,t,i,l,_,h){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="隐藏的调试接口" tabindex="-1">隐藏的调试接口 <a class="header-anchor" href="#隐藏的调试接口" aria-label="Permalink to &quot;隐藏的调试接口&quot;">​</a></h1><p>已注册为命令但未作为用户工具宣传的调试面清单：约 93 个 测试桩程序、diag 类别的 ring-0 自检与芯片组操作、注册表 门禁、在线修复探针，以及每驱动的直通测试面。每个条目都是 真实的已注册程序或 L1SVC op —— 在 <code>ush&gt;</code> 提示符下输入 它的名字即可。关于如何<em>读</em>输出，见 <a href="./debug-handbook.html">debug-handbook.md</a>；完整 op 编号见 <a href="./interface-dictionary.html">interface-dictionary.md</a>。</p><h2 id="_1-如何运行其中任何一个" tabindex="-1">1. 如何运行其中任何一个 <a class="header-anchor" href="#_1-如何运行其中任何一个" aria-label="Permalink to &quot;1. 如何运行其中任何一个&quot;">​</a></h2><ul><li>在 <code>ush&gt;</code> 提示符下输入程序名（它们是注册表条目，由 <code>help -a</code> 呈现）。</li><li>参数（如有注明）与任何命令完全一样地传递 （<code>disk_rw_test hda</code>）；包装程序把 argv 拼进该 op 的 参数行。</li><li>从宿主侧：<code>python3 tools/run_l1_per_app.py</code> 为每个程序 启动一次 ISO 并记录各自输出（每行一个全新进程表）； <code>tools/run_fix4_regression.py</code> 运行固定命令组 （见 <a href="./e2e-suites.html">e2e-suites.md</a>）。</li><li>语法由服务侧拥有：对 l1svc 包装的应用而言，程序只是一根 透明管道 —— &quot;隐藏&quot;开关就是注册表提示永不显示、但服务 会解析的开关。</li></ul><h2 id="_2-测试桩程序-约-93-个" tabindex="-1">2. 测试桩程序（约 93 个） <a class="header-anchor" href="#_2-测试桩程序-约-93-个" aria-label="Permalink to &quot;2. 测试桩程序（约 93 个）&quot;">​</a></h2><p>按所演练的内容分组。&quot;运行&quot;即调用方式；无参数者只写 裸名字。</p><h3 id="_2-1-ota-更新流水线-11-个-config-test" tabindex="-1">2.1 OTA / 更新流水线（11 个 + config_test） <a class="header-anchor" href="#_2-1-ota-更新流水线-11-个-config-test" aria-label="Permalink to &quot;2.1 OTA / 更新流水线（11 个 + config_test）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>程序</th><th>测试内容</th><th>运行</th></tr></thead><tbody><tr><td><code>ab_partition_test</code></td><td>A/B 槽位 + 标志语义</td><td>裸</td></tr><tr><td><code>checkupdate_test</code></td><td>更新检查单元测试</td><td>裸</td></tr><tr><td><code>update_check_test</code></td><td>检查阶段单元测试</td><td>裸</td></tr><tr><td><code>update_download_test</code></td><td>下载阶段单元测试</td><td>裸</td></tr><tr><td><code>update_install_test</code></td><td>安装阶段单元测试</td><td>裸</td></tr><tr><td><code>update_local_test</code></td><td>离线包安装</td><td>裸</td></tr><tr><td><code>update_pkg_test</code></td><td>包清单/校验和</td><td>裸</td></tr><tr><td><code>update_rollback_test</code></td><td>回滚阶段单元测试</td><td>裸</td></tr><tr><td><code>update_status_test</code></td><td>状态阶段单元测试</td><td>裸</td></tr><tr><td><code>update_verify_test</code></td><td>SHA256 校验阶段</td><td>裸</td></tr><tr><td><code>real_update_test</code></td><td>完整真实流程</td><td>裸</td></tr><tr><td><code>config_test</code></td><td>/etc 配置后端</td><td>裸</td></tr></tbody></table><p>配套驱动：<code>tools/make_update_pkg.sh</code>（打包）、E2E 的 <code>tools/fix1_checkupdate_e2e.py</code>。</p><h3 id="_2-2-块设备-存储-8-个" tabindex="-1">2.2 块设备 / 存储（8 个） <a class="header-anchor" href="#_2-2-块设备-存储-8-个" aria-label="Permalink to &quot;2.2 块设备 / 存储（8 个）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>程序</th><th>测试内容</th><th>运行</th></tr></thead><tbody><tr><td><code>ahci_test</code></td><td>AHCI 端口读</td><td>裸</td></tr><tr><td><code>nvme_test</code></td><td>NVMe 命名空间读</td><td>裸</td></tr><tr><td><code>ata_dma_test</code></td><td>ATA bus-master DMA 与 PIO 时序对比</td><td>裸</td></tr><tr><td><code>virtio_blk_test</code></td><td>virtio-blk 往返</td><td>裸</td></tr><tr><td><code>disk_rw_test</code></td><td>原始扇区写/读/比较</td><td><code>disk_rw_test &lt;device&gt;</code></td></tr><tr><td><code>partition_test</code></td><td>分区扫描</td><td><code>partition_test [device]</code></td></tr><tr><td><code>fs_mount_test</code></td><td>格式化 + 挂载往返</td><td><code>fs_mount_test &lt;device&gt;</code>（<strong>会格式化它</strong>）</td></tr><tr><td><code>real_hw_test</code></td><td>真实硬件磁盘 + NIC 普查</td><td>裸</td></tr></tbody></table><h3 id="_2-3-nic-驱动-10-个" tabindex="-1">2.3 NIC 驱动（10 个） <a class="header-anchor" href="#_2-3-nic-驱动-10-个" aria-label="Permalink to &quot;2.3 NIC 驱动（10 个）&quot;">​</a></h3><p><code>e1000e_test</code>、<code>igb_test</code>、<code>ixgbe_test</code>、<code>bcm57xx_test</code>、 <code>rtl810x_test</code>、<code>rtl8125_test</code>、<code>rtl8139_test</code>、 <code>rtl8168_test</code>、<code>nic_rw_test</code>（帧环回）、<code>other_nic_test</code> （尽力而为的家族探测）。全部裸调用。这些是各家族驱动的 <em>直通</em>调试面 —— 每个都打印该驱动自己的寄存器/链路/MAC 状态，而非通用摘要。</p><h3 id="_2-4-音频-8-个" tabindex="-1">2.4 音频（8 个） <a class="header-anchor" href="#_2-4-音频-8-个" aria-label="Permalink to &quot;2.4 音频（8 个）&quot;">​</a></h3><p><code>hda_test</code>、<code>ac97_test</code>、<code>sb16_test</code>、<code>es1370_test</code>、 <code>virtio_snd_test</code>、<code>usb_audio_test</code>（每驱动 500 ms 音调 自检；hda/ac97/virtio 在 48000，sb16/es1370 在 44100）、 <code>audio_rw_test</code>（PCM 环回，48 KB 缓冲区）、 <code>sample_rate_test</code>（caps 位图与 set_rate 协商；无卡时 诚实 SKIPPED；HDA+44100 仅在 QEMU 下报告 caps 位）。 全部裸调用。</p><h3 id="_2-5-usb-7-个" tabindex="-1">2.5 USB（7 个） <a class="header-anchor" href="#_2-5-usb-7-个" aria-label="Permalink to &quot;2.5 USB（7 个）&quot;">​</a></h3><p><code>usb_core_test</code>（枚举 + 控制传输）、<code>usb_hotplug_test</code> （插拔，额外参数）、<code>usb_hub_test</code>（外部集线器）、 <code>usb_kbd_test</code>（HID 键盘）、<code>usb_mouse_test</code>（HID 指针）、 <code>usb_serial_test</code>（CDC-ACM）、<code>usb_storage_test</code> （MSC BOT —— 注册块设备）。全部裸调用。</p><h3 id="_2-6-相机-遗留端口-6-个" tabindex="-1">2.6 相机 + 遗留端口（6 个） <a class="header-anchor" href="#_2-6-相机-遗留端口-6-个" aria-label="Permalink to &quot;2.6 相机 + 遗留端口（6 个）&quot;">​</a></h3><p><code>uvctest</code>（UVC 捕获）、<code>scsitest</code>（块层之上的 SCSI， LSI 53C895A）、<code>gameporttest</code>、<code>paralleltest</code>（SPP 字节）、 <code>irtest</code>（NEC/RC5/RC6/SIRC）、<code>touchtest</code>（i2c-hid 手势）。 全部裸调用。</p><h3 id="_2-7-电源路径-4-个" tabindex="-1">2.7 电源路径（4 个） <a class="header-anchor" href="#_2-7-电源路径-4-个" aria-label="Permalink to &quot;2.7 电源路径（4 个）&quot;">​</a></h3><p><code>poweroff_test</code>、<code>suspend_test</code>（真实 ACPI S3）、 <code>halt_test</code>、<code>reboot_test</code> —— 每个都演练真实路径且可能 结束会话（电源向导在运行它们之前警告 + 确认； halt/reboot 测试诚实地 SKIP 活体观察）。</p><h3 id="_2-8-显示-cjk-5-个" tabindex="-1">2.8 显示 / CJK（5 个） <a class="header-anchor" href="#_2-8-显示-cjk-5-个" aria-label="Permalink to &quot;2.8 显示 / CJK（5 个）&quot;">​</a></h3><p><code>chinesetest</code>、<code>font-test</code>、<code>encoding-test</code>、 <code>ime-test</code>（引擎 + 会话电池：词组/翻页/数字选字协议 断言）、<code>tui-test</code>（TUI 自检结论块，约 4.4 KiB）。 全部裸调用。</p><h3 id="_2-9-内核核心自检-16" tabindex="-1">2.9 内核核心自检（16+） <a class="header-anchor" href="#_2-9-内核核心自检-16" aria-label="Permalink to &quot;2.9 内核核心自检（16+）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>程序</th><th>测试内容</th></tr></thead><tbody><tr><td><code>memtest</code></td><td>内存服务电池</td></tr><tr><td><code>heaptest</code></td><td>堆压力（分配/释放/合并）</td></tr><tr><td><code>heapbounds</code></td><td>堆边界条件</td></tr><tr><td><code>fstest</code></td><td>VFS 压力</td></tr><tr><td><code>vmtest</code></td><td>VMM 单元测试</td></tr><tr><td><code>vmkernelpt</code></td><td>内核页表转储</td></tr><tr><td><code>vmmap</code></td><td>地址空间映射转储</td></tr><tr><td><code>cr3test</code></td><td>CR3 寄存器审计</td></tr><tr><td><code>pftest</code></td><td>缺页处理程序</td></tr><tr><td><code>pmmrace</code></td><td>PMM 分配/释放竞态检测器</td></tr><tr><td><code>irqabitest</code></td><td>IRQ 入口 ABI 探针（rsp mod 16、DF=0）</td></tr><tr><td><code>msitest</code></td><td>MSI/MSI-X 向量投递</td></tr><tr><td><code>timer</code></td><td>软定时器</td></tr><tr><td><code>synctest</code></td><td>自旋锁/信号量/互斥锁/条件变量</td></tr><tr><td><code>multi</code></td><td>3 个交错任务唤醒测试</td></tr><tr><td><code>spawn</code></td><td>后台孵化演示</td></tr><tr><td><code>exc</code></td><td>异常自检报告（与启动计数器共享）</td></tr><tr><td><code>nice</code></td><td>优先级演示 —— <code>nice &lt;tid&gt; &lt;prio 0..31&gt;</code></td></tr></tbody></table><p>外加恢复二人组 <code>crashtest</code>（故障注入，见 <a href="./debug-handbook.html">debug-handbook.md</a> 5.1）与 <code>dumpinfo</code>、 加密二人组 <code>cryptotest</code>/<code>dhtest</code>、<code>l1test</code>（作业/IPC/ 动态链接），以及网络测试 <code>nf_test</code>/<code>tcpcc_test</code>/ <code>tcptest</code>/<code>dnstest</code>。</p><h3 id="_2-10-ring-3-扩展家族-扁平程序-标签-l1" tabindex="-1">2.10 ring-3 扩展家族（扁平程序，标签 l1） <a class="header-anchor" href="#_2-10-ring-3-扩展家族-扁平程序-标签-l1" aria-label="Permalink to &quot;2.10 ring-3 扩展家族（扁平程序，标签 l1）&quot;">​</a></h3><p>编译为扁平遗留程序的内核接口面探针：</p><p><code>fork_test</code>、<code>exec_test</code>、<code>fdref_test</code>、<code>pipe_test</code>、 <code>select_test</code>、<code>select_zero_test</code>、<code>signal_test</code>、 <code>sigsegv_test</code>、<code>sse_test</code>（切换间的 FPU 状态）、 <code>stackovf</code>（用户栈守卫）、<code>int3_user</code>（ring 3 来的 #BP）、 <code>priv_test</code>（IOPB 全拒 —— ring-3 端口访问必须 故障）、<code>pf_test</code>、<code>p3_test</code>（优先级）、<code>mmap_test</code>、 <code>mmap_multi</code>、<code>mprotect_test</code>、<code>g6_test</code>（进程组；异步 汇总 <code>failed tests = 0</code>）、<code>g6_exec_a</code>、<code>g6_exec_b</code>、 <code>g6_oom</code>、<code>g7mmap</code>（BUG-0281），以及动态链接家族 <code>pie_test</code>、<code>reloc_test</code>、<code>so_test</code>、<code>dlsym_test</code>、 <code>dyn_hello</code>、<code>main_dyn</code>，外加 <code>hello</code>、<code>loop</code>（作业测试 目标）和 <code>badapp</code>（故意行为不端 —— 异常 kill 的金丝雀 类别）。</p><h3 id="_2-11-自验证-help-测试-3-道注册表门禁" tabindex="-1">2.11 自验证 help 测试（3 道注册表门禁） <a class="header-anchor" href="#_2-11-自验证-help-测试-3-道注册表门禁" aria-label="Permalink to &quot;2.11 自验证 help 测试（3 道注册表门禁）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>程序</th><th>断言</th></tr></thead><tbody><tr><td><code>help_default_test</code></td><td>默认清单的计数/形状</td></tr><tr><td><code>help_a_test</code></td><td>A-Z 排序不变量</td></tr><tr><td><code>help_wp_test</code></td><td>实时注册表文本的工作包分组</td></tr></tbody></table><p>它们解析注册表文本本身（与 <code>help</code> 所用的同一份 <code>L1SVC L1/APPS</code> 渲染），因此兼任生成 <code>OC_USERPROGS[]</code> 表的运行时回归门禁。</p><h3 id="_2-12-在线修复探针-1-个" tabindex="-1">2.12 在线修复探针（1 个） <a class="header-anchor" href="#_2-12-在线修复探针-1-个" aria-label="Permalink to &quot;2.12 在线修复探针（1 个）&quot;">​</a></h3><p><code>p2test &lt;utf8|read0|pipe&gt;</code>：</p><ul><li><code>utf8</code> 把 174 个汉字（522 字节，一次系统调用）推过两条 写路径（控制台 + 串口编码）；</li><li><code>read0</code> 检查 POSIX <code>read(0, buf, 0) == 0</code>；</li><li><code>pipe</code> 对管道槽位复用做 100 轮锤击。</li></ul><p>由 <code>tools/wp_p2_batch_a_test.py</code> 经 QEMU 串口控制台驱动 （批次 A 在线探针：read0 #14、pipe 槽位泄漏 #9）。</p><h2 id="_3-diag-类别的隐藏深度-39-个-op" tabindex="-1">3. diag 类别的隐藏深度（39 个 op） <a class="header-anchor" href="#_3-diag-类别的隐藏深度-39-个-op" aria-label="Permalink to &quot;3. diag 类别的隐藏深度（39 个 op）&quot;">​</a></h2><p>在生命体征（1-8）之外，还有普通用户永远遇不到的两组：</p><ul><li><strong>G9 ring-0 自检（op 9-26）</strong>：cr3test、exc、pftest、 pmmrace、vmtest、vmkernelpt、vmmap、memtest、heaptest、 heapbounds、irqabitest、timer、msitest、spawn、multi、 nice、synctest、fstest —— 与上面的应用相同的函数体， 经 L1SVC 到达而无需包装程序。其中五个 （vmmap/pftest/cr3test/vmkernelpt）运行在一个 <strong>切换到内核 AS 的包裹</strong>内：它们的 v2.2.0 语义依赖 内核地址空间为当前空间，因此分发器从 ring-3 系统调用 重建该上下文，并在返回前恢复孵化者的 AS。</li><li><strong>G10 芯片组操作（op 27-39）</strong>：acpi、acpidev、acpipow、 acpitest（AML 解析器）、pcidump（<code>pcidump &lt;bus:dev.fn&gt;</code> 例如 <code>0:1f.3</code> —— 完整配置空间）、pcibars、pcie、 i2cdetect、i2cget（<code>i2cget &lt;bus&gt; &lt;addr&gt; [reg]</code>，十六进制）、 i2cset（<code>i2cset &lt;bus&gt; &lt;addr&gt; &lt;reg&gt; &lt;val&gt;</code>）、i2ctest、 smbus、smbustest（字节/字/块往返）。</li></ul><h2 id="_4-值得了解的隐藏参数" tabindex="-1">4. 值得了解的隐藏参数 <a class="header-anchor" href="#_4-值得了解的隐藏参数" aria-label="Permalink to &quot;4. 值得了解的隐藏参数&quot;">​</a></h2><p>注册表提示永不显示这些；由服务解析：</p><table tabindex="0"><thead><tr><th>命令</th><th>隐藏参数</th><th>效果</th></tr></thead><tbody><tr><td><code>top</code></td><td><code>-n N</code></td><td>刷新 N 次（钳位 1..10），间隔 1 秒</td></tr><tr><td><code>ln</code></td><td><code>-s &lt;target&gt; &lt;linkpath&gt;</code></td><td>符号链接而非硬链接</td></tr><tr><td><code>sed</code></td><td><code>s/old/new/[g]</code>、<code>-n Np</code>、<code>Nd</code></td><td>替换 / 打印第 N 行 / 删除第 N 行</td></tr><tr><td><code>p2test</code></td><td><code>utf8 | read0 | pipe</code></td><td>探针选择器（见上）</td></tr><tr><td><code>health</code></td><td><code>watch</code> / <code>export [path]</code></td><td>不同的 L1SVC op</td></tr><tr><td>8 个 mega 应用</td><td><code>direct</code></td><td>跳过字面词，原样直通</td></tr><tr><td><code>help</code></td><td><code>-a</code> / <code>--all</code>、<code>-w</code> / <code>--wp</code></td><td>完整 A-Z / 分组清单</td></tr><tr><td><code>update</code></td><td><code>status</code>、<code>--status</code>、<code>--local &lt;path&gt;</code>、<code>local &lt;path&gt;</code></td><td>状态视图 / 离线安装</td></tr><tr><td><code>dns</code></td><td><code>[aaaa|cname|mx|txt|ns|srv]</code></td><td>记录类型选择器</td></tr><tr><td><code>wget</code></td><td><code>https://...</code> 或三参数 <code>host port path</code></td><td>TLS 路径 / 遗留位置形式</td></tr><tr><td><code>ssh</code></td><td><code>[port=2222] [user=oc] [password=oc|&quot;-&quot;]</code></td><td><code>-</code> = 经 /etc/ssh_client_key 的公钥</td></tr><tr><td><code>ime</code></td><td><code>-i</code></td><td>交互式拼音合成行（数字选字、空格 = 首选、PgUp/PgDn 或 -/=/= 翻页、Backspace 退一字、Enter 提交原文、Esc 取消）</td></tr><tr><td><code>dmesg</code></td><td><code>[N]</code></td><td>行数 1..1024（默认 30）</td></tr><tr><td><code>uname</code></td><td><code>[-a]</code></td><td>完整身份字符串</td></tr><tr><td><code>serial_encoding</code></td><td><code>[utf8|gbk]</code></td><td>COM1 tee 编码</td></tr><tr><td><code>sleep</code></td><td>小数秒</td><td><code>sleep 0.5</code> = 500 ms 延迟（不是挂起）</td></tr></tbody></table><h2 id="_5-nic-直通面-wifi-bt" tabindex="-1">5. NIC 直通面（wifi / bt） <a class="header-anchor" href="#_5-nic-直通面-wifi-bt" aria-label="Permalink to &quot;5. NIC 直通面（wifi / bt）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>模式</th></tr></thead><tbody><tr><td><code>wifi</code></td><td>裸 = 适配器 + 家族注册表状态；<code>wifi scan</code> = 被动信标扫描（QEMU 下诚实的 &quot;no radio&quot;）；<code>wifi test</code> = 802.11 核心 + 各家族自检（无硬件的家族按名列出）；<code>wifi sdio</code> = SDHCI 总线状态 + 自检</td></tr><tr><td><code>bt</code></td><td>裸 = 传输 + 控制器状态；<code>bt usb</code> = HCI-USB 传输；<code>bt uart</code> = H4 UART 传输；<code>bt test</code> = 流自检（经 COM2 H4 字节进入 <code>tools/bt_test_peer.py</code> 的真实 E2E）</td></tr></tbody></table><h2 id="_6-usb-测试-op-9-个-op-的调试面" tabindex="-1">6. USB 测试 op（9 个 op 的调试面） <a class="header-anchor" href="#_6-usb-测试-op-9-个-op-的调试面" aria-label="Permalink to &quot;6. USB 测试 op（9 个 op 的调试面）&quot;">​</a></h2><p>类别 17 把整个 USB 栈的自检暴露为一等 op：<code>usb</code>（状态）、 <code>usbdev [slot]</code>（逐设备细节），然后是 <code>usb_core_test</code>、 <code>usb_kbd_test</code>、<code>usb_mouse_test</code>、<code>usb_storage_test</code>、 <code>usb_serial_test</code>、<code>usb_hotplug_test [...]</code>、 <code>usb_hub_test</code>。内核侧轮询线程（<code>driver_usb_poll_start</code>） 在 kmain 中启动并常驻。</p><h2 id="_7-启动期自检-非命令" tabindex="-1">7. 启动期自检（非命令） <a class="header-anchor" href="#_7-启动期自检-非命令" aria-label="Permalink to &quot;7. 启动期自检（非命令）&quot;">​</a></h2><p>有两个在 shell 存在之前运行 —— 它们的行出现在每份启动 日志里：</p><ul><li><code>l1_ext_self_test()</code> —— &quot;WP-01 ext self-test: N/4 points reachable&quot;（探测 4 个扩展点：fb 访问、渲染器、字体 引擎、控制台钩子）。</li><li><code>arch_exc_tests()</code> —— &quot;exception self-test: N/3 (#DE/#UD/ #PF) caught, kernel alive&quot; —— 与 <code>exc</code> 命令共享通过 计数器。</li></ul><h2 id="_8-让这一切保持诚实的注册表门禁" tabindex="-1">8. 让这一切保持诚实的注册表门禁 <a class="header-anchor" href="#_8-让这一切保持诚实的注册表门禁" aria-label="Permalink to &quot;8. 让这一切保持诚实的注册表门禁&quot;">​</a></h2><ul><li><code>make userprogs-check</code> —— 任何 l1apps 源文件 / 接口头 文件 / i18n json 比生成的 <code>userprogs_data.h</code> 新超过 2 秒时让 <code>make dist</code> 失败。</li><li><code>tools/run_fix4_regression.py</code> 检查 6 —— 注册表下限： <code>help -a</code> 必须列出 &gt;= 276 个程序（实测 284）。</li><li><code>help_*_test</code>（2.11 节）—— 运行时形状断言。</li><li><code>tools/gen_api_docs.py</code> —— 从<em>实时</em> <code>help -a</code> 捕获再生成 <code>docs/data/*.json</code> 与 292 个命令页，容忍串口回显重叠 （<code>[tag]</code> 括号是可选的，因为回显重叠可能吃掉 <code>&quot;ega]&quot;</code> 的前导 <code>&quot;e&quot;</code>）。</li></ul>',51)])])}const u=e(a,[["render",r]]);export{n as __pageData,u as default};
